-- 表说明：拜特T6服务管理
CREATE TABLE IF NOT EXISTS `bt_app_manager`
(
    `id`          int          NOT NULL AUTO_INCREMENT,
    `app_name`    varchar(100) DEFAULT NULL COMMENT '应用名',
    `app_name_en` varchar(100) DEFAULT NULL COMMENT '应用名英文 理论对应微服务注册名称',
    `create_by`   varchar(100) DEFAULT NULL COMMENT '创建人',
    `create_date` datetime     DEFAULT NULL COMMENT '创建时间',
    `TENANT_ID`   varchar(32)  DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`id`) USING BTREE,
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  ROW_FORMAT = DYNAMIC COMMENT = '拜特T6服务管理';


-- 表说明：bt_input_bank_swift_manager
CREATE TABLE IF NOT EXISTS `bt_input_bank_swift_manager`
(
    `ID`          varchar(32)  NOT NULL,
    `BANK_CODE`   varchar(30)  NOT NULL,
    `BANK_NAME`   varchar(200) NOT NULL,
    `SWIFT_CODE`  varchar(200) DEFAULT NULL,
    `CREATE_DATE` datetime     DEFAULT NULL,
    `CREATE_BY`   varchar(32)  DEFAULT NULL,
    `UPDATE_DATE` datetime     DEFAULT NULL,
    `UPDATE_BY`   varchar(32)  DEFAULT NULL,
    `TENANT_ID`   varchar(32)  DEFAULT NULL COMMENT '租户ID',
    `IS_INIT`     char(1)      DEFAULT '1' COMMENT '是否初始化',
    PRIMARY KEY (`ID`),
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


