-- 表说明：bt_m_act_hi_actinst
CREATE TABLE IF NOT EXISTS `bt_m_act_hi_actinst`
(
    `ID_`                varchar(128)  NOT NULL,
    `REV_`               decimal(20,6) DEFAULT '1.000000',
    `PROC_DEF_ID_`       varchar(128)  NOT NULL,
    `PROC_INST_ID_`      varchar(128)  NOT NULL,
    `EXECUTION_ID_`      varchar(128)  NOT NULL,
    `ACT_ID_`            varchar(510)  NOT NULL,
    `TASK_ID_`           varchar(128)  DEFAULT NULL,
    `CALL_PROC_INST_ID_` varchar(128)  DEFAULT NULL,
    `ACT_NAME_`          varchar(510)  DEFAULT NULL,
    `ACT_TYPE_`          varchar(510)  NOT NULL,
    `ASSIGNEE_`          varchar(510)  DEFAULT NULL,
    `START_TIME_`        datetime      NOT NULL,
    `END_TIME_`          datetime      DEFAULT NULL,
    `DURATION_`          decimal(20,6) DEFAULT NULL,
    `DELETE_REASON_`     varchar(4000) DEFAULT NULL,
    `TENANT_ID_`         varchar(510)  DEFAULT '''''\r\n',
    PRIMARY KEY (`ID_`),
    KEY `ACT_IDX_HI_ACT_INST_START_END` (`START_TIME_`, `END_TIME_`),
    KEY `ACT_IDX_HI_ACT_INST_END` (`END_TIME_`),
    KEY `ACT_IDX_HI_ACT_INST_PROCINST` (`PROC_INST_ID_`, `ACT_ID_`),
    KEY `ACT_IDX_HI_ACT_INST_COMP` (`EXECUTION_ID_`, `ACT_ID_`, `END_TIME_`, `ID_`),
    KEY `ACT_IDX_HI_ACT_INST_TENANT_ID` (`TENANT_ID_`),
    KEY `ACT_IDX_HI_AI_PDEFID_END_TIME` (`PROC_DEF_ID_`, `END_TIME_`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  ROW_FORMAT = DYNAMIC;


