-- 表说明：bt_m_bpm_delegation
CREATE TABLE IF NOT EXISTS `bt_m_bpm_delegation`
(
    `ID`            varchar(32)    NOT NULL,
    `PRINCIPAL`     varchar(32)    DEFAULT NULL COMMENT '授权人',
    `PROXY`         varchar(32)    DEFAULT NULL COMMENT '被授权人',
    `STATUS`        decimal(65,30) DEFAULT NULL COMMENT '1、暂存 2、待确认 3、打回 4、已确认 5、结束',
    `START_TIME`    datetime       DEFAULT NULL COMMENT '开始时间',
    `END_TIME`      datetime       DEFAULT NULL COMMENT '结束时间',
    `CREATE_BY`     varchar(32)    DEFAULT NULL,
    `UPDATE_BY`     varchar(32)    DEFAULT NULL,
    `CREATE_TIME`   datetime       DEFAULT NULL,
    `UPDATE_TIME`   datetime       DEFAULT NULL,
    `DELEGATION_NO` varchar(20)    NOT NULL COMMENT '序列号',
    `CORP_ID`       varchar(32)    DEFAULT NULL,
    PRIMARY KEY (`ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：bt_m_bpm_delegation_category
