    PRIMARY KEY (`ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：bt_m_bpm_option
CREATE TABLE IF NOT EXISTS `bt_m_bpm_option`
(
    `ID`              varchar(32)  NOT NULL,
    `CATEGORY`        varchar(32)  DEFAULT NULL COMMENT '所属流程分类',
    `NAME`            varchar(20)  DEFAULT NULL COMMENT '配置名称',
    `FIELD_NAME`      varchar(30)  DEFAULT NULL COMMENT '流程条件字段名',
    `EVENT`           varchar(100) DEFAULT NULL COMMENT '任务节点事件',
    `TYPE`            decimal(1,0) DEFAULT NULL COMMENT '类型 1、流向。2、任务节点',
    `SELECT_TYPE`     varchar(2)   DEFAULT NULL,
    `DICT_GROUP`      varchar(200) DEFAULT NULL,
    `MSG_TPL`         varchar(255) DEFAULT NULL COMMENT '手机端的模版消息',
    `CREATE_TIME`     datetime     DEFAULT NULL,
    `UPDATE_TIME`     datetime     DEFAULT NULL,
    `VISIBLE`         tinyint      DEFAULT NULL,
    `SORT`            tinyint      DEFAULT NULL,
    `IS_STABLE_FIELD` tinyint      DEFAULT NULL,
    PRIMARY KEY (`ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


