-- 表说明：bt_swift_info_manager
CREATE TABLE IF NOT EXISTS `bt_swift_info_manager`
(
    `ID`             varchar(32)  NOT NULL,
    `SWIFT_CODE`     varchar(100) DEFAULT NULL COMMENT 'swift code',
    `BANK_NAME`      varchar(200) DEFAULT NULL COMMENT '机构名称',
    `country_code`   varchar(32)  DEFAULT NULL,
    `CITY_NAME`      varchar(100) DEFAULT NULL COMMENT '所在城市',
    `BANK_ADD`       varchar(300) DEFAULT NULL COMMENT '地址',
    `CREATE_DATE`    datetime     DEFAULT NULL COMMENT '创建时间',
    `CREATE_BY`      varchar(32)  DEFAULT NULL COMMENT '创建人',
    `UPDATE_DATE`    datetime     DEFAULT NULL COMMENT '更新时间',
    `UPDATE_BY`      varchar(32)  DEFAULT NULL COMMENT '更新人',
    `CLS_FLAG`       varchar(10)  DEFAULT NULL,
    `LOCAL_CLEAR_NO` varchar(30)  DEFAULT NULL COMMENT '本地清算号',
    `BANK_TYPE_ID`   varchar(32)  DEFAULT NULL COMMENT '银行类型id。取自 bt_bank_type',
    `STATUS`         decimal(2,0) DEFAULT NULL COMMENT '状态。字典common.status',
    `IS_INIT`        char(1)      DEFAULT '1' COMMENT '是否初始化',
    PRIMARY KEY (`ID`),
    KEY `IDX_BT_SWIFT_INFO_SC` (`SWIFT_CODE`),
    KEY `IDX_BT_SWIFT_INFO_BN` (`BANK_NAME`),
    KEY `IDX_BT_SWIFT_INFO_SC_BA` (`SWIFT_CODE`, `BANK_ADD`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：fc_excrate_adjust_manager
CREATE TABLE IF NOT EXISTS `fc_excrate_adjust_manager`
(
    `ID`                        varchar(32)    NOT NULL COMMENT 'id',
    `CUR_ID`                    varchar(32)    NOT NULL COMMENT '币别',
    `REFER_CUR_ID`              varchar(32)    NOT NULL COMMENT '参考币别',
