    `OLD_EXCHANGE_RATE`         decimal(20,12) DEFAULT NULL,
    `NEW_EXCHANGE_RATE`         decimal(20,12) DEFAULT NULL,
    `RMK`                       text           COMMENT '备注',
    `STATUS`                    decimal(4,0)   DEFAULT NULL COMMENT '状态',
    `CREATE_DATE`               datetime       DEFAULT NULL,
    `CREATE_BY`                 varchar(32)    DEFAULT NULL,
    `UPDATE_DATE`               datetime       DEFAULT NULL,
    `UPDATE_BY`                 varchar(32)    DEFAULT NULL,
    `TYPE_ID`                   varchar(32)    DEFAULT NULL,
    `FOREIGN_EXCHANGE_PURCHASE` decimal(20,12) DEFAULT NULL,
    `FOREIGN_EXCHANGE_SELL`     decimal(20,12) DEFAULT NULL,
    `FOREIGN_EXCHANGE_MIDDLE`   decimal(20,12) DEFAULT NULL,
    `TENANT_ID`                 varchar(32)    DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`ID`),
