-- 表说明：签约/变更记录
CREATE TABLE IF NOT EXISTS `sys_sign_record_manager`
(
    `ID`               varchar(32)   NOT NULL COMMENT '主键',
    `TENANT_CODE`      varchar(32)   NOT NULL COMMENT '企业客户号',
    `TENANT_NAME`      varchar(300)  NOT NULL COMMENT '企业名称',
    `BILL_CODE`        varchar(32)   DEFAULT NULL COMMENT '单据号',
    `SOURCE_BILL_CODE` varchar(32)   DEFAULT NULL COMMENT '源单编号',
    `BUS_TYPE`         decimal(3,0)  NOT NULL COMMENT '业务类型',
    `SIGN_DATE`        datetime      NOT NULL COMMENT '签约日期',
    `TENANT_STATUS`    decimal(3,0)  NOT NULL COMMENT '客户状态',
    `EXPIRY_DATE`      datetime      DEFAULT NULL COMMENT '解约/失效日期',
    `CORP_ID`          varchar(32)   NOT NULL COMMENT '签约机构id',
    `CHANGE_DATE`      datetime      NOT NULL COMMENT '新增/变更日期',
    `CHANGE_REASONS`   varchar(2000) DEFAULT NULL COMMENT '变更原因',
    `CHANGE_VERSION`   int           NOT NULL COMMENT '变更版本',
    `CREATE_BY`        varchar(32)   DEFAULT NULL COMMENT '创建人',
    `CREATE_TIME`      datetime      DEFAULT NULL COMMENT '创建时间',
    `UPDATE_BY`        varchar(32)   DEFAULT NULL COMMENT '修改人',
    `UPDATE_TIME`      datetime      DEFAULT NULL COMMENT '修改时间',
    PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  COMMENT = '签约/变更记录';


