) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：签约客户管理
CREATE TABLE IF NOT EXISTS `sys_tenant_manager`
(
    `ID`                       varchar(32)   NOT NULL COMMENT '主键',
    `TENANT_CODE`              varchar(32)   NOT NULL COMMENT '企业客户号',
    `TENANT_NAME`              varchar(300)  NOT NULL COMMENT '企业名称',
    `TENANT_ENGLISH_NAME`      varchar(300)  DEFAULT NULL COMMENT '企业名称（英文）',
    `POST_CODE`                varchar(20)   DEFAULT NULL COMMENT '邮政编码',
    `TENANT_CERT_TYPE`         varchar(2)    NOT NULL COMMENT '企业证件类型',
    `TENANT_CERT_CODE`         varchar(50)   NOT NULL COMMENT '企业证件号码',
    `TENANT_CERT_INDATE`       date          NOT NULL COMMENT '企业证件有效期',
    `TENANT_PHONE`             varchar(20)   DEFAULT NULL COMMENT '企业联系电话',
    `TENANT_ADDR`              varchar(300)  DEFAULT NULL COMMENT '企业地址',
    `LEGAL_PERSON_NAME`        varchar(100)  NOT NULL COMMENT '法人/负责人',
    `LEGAL_PERSON_MOBILE`      varchar(11)   NOT NULL COMMENT '法人/负责人联系方式',
    `LEGAL_PERSON_CERT_TYPE`   varchar(2)    NOT NULL COMMENT '法人/负责人证件类型：01-居民身份证、02-户口簿、03-护照',
    `LEGAL_PERSON_CERT_CODE`   varchar(50)   NOT NULL COMMENT '法人/负责人证件号码',
    `LEGAL_PERSON_CERT_INDATE` date          NOT NULL COMMENT '法人/负责人证件有效期',
    `ATTN`                     varchar(100)  DEFAULT NULL COMMENT '企业经办人',
    `ATTN_PHONE`               varchar(20)   DEFAULT NULL COMMENT '经办人联系电话',
    `ATTN_EMAIL`               varchar(100)  DEFAULT NULL COMMENT '经办人邮箱',
    `CORP_ID`                  varchar(32)   NOT NULL COMMENT '签约机构id',
    `SIGN_CHANNELS`            varchar(2)    NOT NULL COMMENT '签约渠道：01-柜面、02-线上网银',
    `IS_SAME_SUB_BANK`         varchar(2)    DEFAULT NULL COMMENT '是否同分行：0-否，1-是',
    `AM_USER_ID`               varchar(32)   NOT NULL COMMENT '客户经理',
    `ATTN_USER_ID`             varchar(32)   DEFAULT NULL COMMENT '经办用户',
    `TENANT_STATUS`            decimal(3,0)  NOT NULL COMMENT '客户状态',
    `SIGN_DATE`                datetime      NOT NULL COMMENT '签约日期',
    `ENABLE_DATE`              datetime      DEFAULT NULL COMMENT '启用日期',
    `STATUS`                   decimal(10,0) DEFAULT NULL COMMENT '审批状态',
    `TENANT_ID`                varchar(32)   DEFAULT NULL COMMENT '租户id；默认与签约客户的企业客户号相同',
    `CHARGE_MODE`              varchar(2)    NOT NULL DEFAULT '0' COMMENT '双管理员模式: 0：否 1：是',
    `BILL_CODE`                varchar(32)   DEFAULT NULL COMMENT '单据号',
    `SOURCE_BILL_CODE`         varchar(32)   DEFAULT NULL COMMENT '源单编号',
    `ATTACHMENT_ID`            varchar(32)   DEFAULT NULL COMMENT '附件ID',
    `CREATE_BY`                varchar(32)   DEFAULT NULL COMMENT '创建人',
    `CREATE_TIME`              datetime      DEFAULT NULL COMMENT '创建时间',
    `UPDATE_BY`                varchar(32)   DEFAULT NULL COMMENT '修改人',
    `UPDATE_TIME`              datetime      DEFAULT NULL COMMENT '修改时间',
    `CORP_NUMBER`              int           default 100 not null comment '单位数量',
    `USER_NUMBER`              int           default 100 not null comment '用户数量',
    `ACCOUNT_NUMBER`           int           default 100 not null comment '银行账号数量',
    PRIMARY KEY (`ID`) USING BTREE,
    KEY `IDX_SYS_TENANT_STATUS` (`ID`, `STATUS`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  COMMENT = '签约客户管理';


