-- 表说明：tenant_pre_fbs_item
CREATE TABLE IF NOT EXISTS `tenant_pre_fbs_item`
(
    `ID`               varchar(32)   NOT NULL COMMENT '主建',
    `ITEM_CODE`        varchar(40)   NOT NULL COMMENT '科目代码',
    `ITEM_NAME`        varchar(100)  DEFAULT NULL COMMENT '科目名称',
    `SUPER_ITEM_CODE`  varchar(40)   DEFAULT NULL COMMENT '父科目',
    `LEVELS`           decimal(5,0)  DEFAULT NULL COMMENT '科目层级',
    `SIGN`             decimal(5,0)  DEFAULT NULL COMMENT '资金流向1， 资金流入-1 ，资金流出',
    `IS_INTERNAL`      varchar(1)    NOT NULL COMMENT '是否冲抵科目  1-是 0-否',
    `IS_CONTROL`       varchar(1)    DEFAULT NULL COMMENT '是否计划控制科目 1-是 0-否',
    `IS_RIGID`         varchar(1)    DEFAULT NULL COMMENT '是否刚性科目 1-是 0-否',
    `IS_BEGIN_PERIOD`  varchar(1)    DEFAULT NULL COMMENT '是否期初科目 1-是 0-否',
    `IS_END_PERIOD`    varchar(1)    DEFAULT NULL COMMENT '是否期末科目 1-是 0-否',
    `VALID_SIGN`       varchar(1)    NOT NULL COMMENT '有效标志 0 无效 1 有效',
    `ITEM_RELATION`    text         ,
    `OVER_PER_SPEND`   decimal(10,2) DEFAULT NULL COMMENT '超计划比例',
    `RMK`              varchar(200)  DEFAULT NULL COMMENT '备注',
    `IS_SYSTEM`        varchar(1)    DEFAULT NULL COMMENT '是否系统科目（系统科目不能删除）系统科目：100-期初资金，200-资金增加，300-可用资金，400-资金减少，500-资金不足或多余，600-新增筹资或还款，700-期末资金，800表外科目',
    `seq_code`         varchar(1000) DEFAULT NULL,
    `SUPER_ITEM_CODES` varchar(150)  DEFAULT NULL COMMENT '存父的所有的编码,用逗号分隔',
    `IS_WRITE`         char(1)       DEFAULT NULL COMMENT '是否允许填写计划 1-是 0-否',
    `CREATE_DATE`      datetime      DEFAULT NULL,
    `CREATE_BY`        varchar(32)   DEFAULT NULL,
    `UPDATE_DATE`      datetime      DEFAULT NULL,
    `UPDATE_BY`        varchar(32)   DEFAULT NULL,
    `CASH_ITEM_CODE`   varchar(60)   DEFAULT NULL,
    `CASH_ITEM_NAME`   varchar(100)  DEFAULT NULL,
    `ALLOT_ITEM_CODE`  varchar(40)   DEFAULT NULL,
    `IS_WRITE_DETAIL`  varchar(1)    DEFAULT '0',
    `IS_INIT`          char(1)       DEFAULT '1'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


