-- 表说明：tenant_pre_menu
CREATE TABLE IF NOT EXISTS `tenant_pre_menu`
(
    `id`          varchar(65)   NOT NULL,
    `CODE`        varchar(32)   DEFAULT NULL,
    `DESCRIPTION` varchar(200)  DEFAULT NULL,
    `NAME`        varchar(50)   NOT NULL,
    `PARENT_ID`   varchar(65)   DEFAULT NULL,
    `PARENT_IDS`  text         ,
    `SORT`        decimal(10,0) NOT NULL,
    `STATUS`      decimal(10,0) NOT NULL,
    `URL`         varchar(255)  DEFAULT NULL,
    `NET_ID`      varchar(32)   DEFAULT NULL,
    `ICON`        varchar(50)   DEFAULT NULL COMMENT '图标',
    `CREATE_TIME` datetime      DEFAULT NULL,
    `CREATE_BY`   varchar(32)   DEFAULT NULL,
    `UPDATE_TIME` datetime      DEFAULT NULL,
    `UPDATE_BY`   varchar(32)   DEFAULT NULL,
    `IS_MODULE`   decimal(2,0)  DEFAULT NULL COMMENT '是否为模块，1是，0否',
    `IS_EXTEND`   decimal(1,0)  DEFAULT NULL,
    `OLD_ICON`    varchar(50)   DEFAULT NULL,
    `IS_INIT`     char(1)       DEFAULT '1',
    `ui_version`  varchar(10)   DEFAULT NULL COMMENT '是否为前后端分离，1是，0否'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：tenant_p_notification_category
CREATE TABLE IF NOT EXISTS `tenant_p_notification_category`
(
    `ID`                 varchar(65)   NOT NULL,
    `PARENT_ID`          varchar(65)   DEFAULT NULL,
    `NAME`               varchar(50)   DEFAULT NULL,
    `TAG`                varchar(100)  DEFAULT NULL,
    `MENU_ID`            varchar(65)   DEFAULT NULL,
    `LIST_URL`           varchar(255)  DEFAULT NULL,
    `DETAIL_URL`         varchar(255)  DEFAULT NULL,
    `RESOURCE_CONTENT`   varchar(255)  DEFAULT NULL,
    `ROLE_FILTER`        decimal(2,0)  DEFAULT NULL COMMENT '是否过滤角色',
    `SORT`               decimal(4,0)  DEFAULT NULL,
    `CONTENT`            varchar(2000) DEFAULT NULL COMMENT '消息模版内容',
    `TYPE`               decimal(2,0)  DEFAULT NULL COMMENT '1、通知。2、待处理',
    `STAR_TARGET`        varchar(10)   DEFAULT NULL,
    `MENU_NAME`          varchar(100)  DEFAULT NULL COMMENT '菜单名称',
    `WEIXIN_IND`         smallint      DEFAULT NULL,
    `NOTIFY_OBJECT_TYPE` int           DEFAULT NULL COMMENT '提醒对象类型 0-所有角色；1-按角色发送； 2-按用户发送',
    `IS_INIT`            char(1)       DEFAULT '1' COMMENT '是否初始化'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：tenant_pre_resources
CREATE TABLE IF NOT EXISTS `tenant_pre_resources`
(
    `ID`          varchar(65)   NOT NULL,
    `DESCRIPTION` varchar(200)  DEFAULT NULL,
    `NAME`        varchar(64)   NOT NULL,
    `PERMISSION`  varchar(200)  DEFAULT NULL,
    `STATUS`      decimal(10,0) NOT NULL,
    `MENU_ID`     varchar(65)   DEFAULT NULL,
    `CREATE_TIME` datetime      DEFAULT NULL,
    `CREATE_BY`   varchar(32)   DEFAULT NULL,
    `UPDATE_TIME` datetime      DEFAULT NULL,
    `UPDATE_BY`   varchar(32)   DEFAULT NULL,
    `URL`         varchar(1000) DEFAULT NULL,
    `IS_INIT`     char(1)       DEFAULT '1',
    `ui_version`  varchar(10)   DEFAULT NULL COMMENT '是否为前后端分离，1是，0否'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：贷款期限表
CREATE TABLE IF NOT EXISTS `tenant_pre_tb_credit_period`
(
    `ID`                 varchar(32)  NOT NULL COMMENT '主键',
    `CODE`               varchar(32)  NOT NULL COMMENT '贷款周期的编码',
    `PERIOD_NAME`        varchar(128) DEFAULT NULL COMMENT '贷款周期的名称',
    `PERIOD`             decimal(2,0) DEFAULT NULL COMMENT '贷款期数',
    `PERIOD_CYCLE`       decimal(1,0) DEFAULT NULL COMMENT '贷款期数类型',
    `MONEY_TYPE`         decimal(2,0) DEFAULT NULL COMMENT '货币类型',
    `CREDIT_DAYS`        decimal(6,0) DEFAULT NULL COMMENT '贷款的总天数',
    `IS_SYSVALUE`        varchar(10)  DEFAULT NULL COMMENT '是否为系统预设值',
    `LOAN_CLASS`         varchar(2)   DEFAULT NULL COMMENT '贷款种类',
    `INTEREST_RATE_TYPE` decimal(1,0) DEFAULT NULL,
    `REMARK`             varchar(200) DEFAULT NULL,
    `DEPOSIT_ACC_SIGN`   char(1)      DEFAULT '0',
    `IS_INIT`            char(1)      DEFAULT '1',
    PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  ROW_FORMAT = DYNAMIC COMMENT = '贷款期限表';


-- 表说明：bt_currency_manager
CREATE TABLE IF NOT EXISTS `bt_currency_manager`
(
    ID               varchar(32)      not null comment 'id',
    CUR_CODE         varchar(10)      not null comment '币别编码',
    CUR_NAME         varchar(30)      not null comment '币别名称',
    ENGLISH_CODE     varchar(30)      null comment '英文简码',
    CUR_EXRATE       decimal(12, 4)                       null comment '汇率',
    CUR_SIGN         varchar(10)      null comment '币别符号',
    NATURAL_SIGN     varchar(1)       null comment '是否本位币',
    PB_SCALE_CODE    varchar(20)      null comment '人行编码',
    RMK              varchar(255)     null comment '备注',
    VALID_SIGN       varchar(1)       null comment '有效标志',
    CREATE_DATE      datetime                             null,
    CREATE_BY        varchar(32)      null,
    UPDATE_DATE      datetime                             null,
    UPDATE_BY        varchar(32)      null,
    IS_SYSTEM        varchar(1)       null comment '是否系统初始化',
    NONWORK_DAY_RULE char default '1' null,
    NONWORK_DAY      varchar(30)      null,
    SYS_CUR_ID       varchar(32)      null,
    IS_INIT          char                     default '1' null comment '是否初始化',
    PRIMARY KEY (`ID`),
    KEY `IDX_CURRENCY_ID_CODE` (`ID`, `ENGLISH_CODE`)
)
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;


-- 表说明：内管的系统参数配置
CREATE TABLE IF NOT EXISTS `sys_config_manager`
(
    ID        varchar(32)  not null,
    TYPE      varchar(50)  null comment '配置类型',
    NAME      varchar(50)  null comment '配置名',
    VALUE     varchar(500) null comment '配置值',
    `CHANGE` varchar(1) null,
    TENANT_ID varchar(32)  null comment '租户ID',
    PRIMARY KEY (`ID`),
    UNIQUE KEY `TYPE` (`TYPE`, `NAME`, `TENANT_ID`),
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
)
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  COMMENT = '内管的系统参数配置';
192.168.1.10-192.168.1.100', null, null);


-- 表说明：bt_rate_type_manager
CREATE TABLE IF NOT EXISTS `bt_rate_type_manager`
(
    ID             varchar(32)            not null,
    TYPE_NAME      varchar(100)           null,
    RMK            varchar(200)           null,
    VALID_SIGN     varchar(1) default '1' null,
    CREATE_BY      varchar(32)            null,
    CREATE_DATE    datetime                                   null,
    UPDATE_BY      varchar(32)            null,
    UPDATE_DATE    datetime                                   null,
    DECIMAL_PLACES decimal(4)                     default 4   null,
    TENANT_ID      varchar(32)            null comment '租户ID',
    PRIMARY KEY (`ID`),
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
)
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin;

