-- 表说明：日历管理表
CREATE TABLE IF NOT EXISTS `sys_calendar_manager`
(
    ID                   varchar(32) NOT NULL COMMENT '主键ID',
    CALENDAR_NUM         decimal(14,0) NOT NULL COMMENT '',
    WORK_DAY_SIGN        decimal(6,0) NOT NULL COMMENT '',
    MONTH_END_SIGN       decimal(6,0) NOT NULL COMMENT '',
    YEAR_END_SIGN        decimal(6,0) NOT NULL COMMENT '',
    CREATE_DATE          datetime NULL DEFAULT NULL COMMENT '',
    CREATE_BY            varchar(32) NULL DEFAULT NULL COMMENT '',
    COUNTRY_ID           varchar(65) NULL DEFAULT NULL COMMENT '',
    CUR_ID               varchar(32) NULL DEFAULT NULL COMMENT '',
    IS_INIT              char(1) NULL DEFAULT '1' COMMENT '是否初始化',
    PRIMARY KEY (`ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  COMMENT = '日历管理表';


-- 表说明：国家表
CREATE TABLE IF NOT EXISTS `sys_country`
(
    `ID`          varchar(32)  NOT NULL,
    `CODE`        varchar(30)  DEFAULT NULL,
    `NAME_ZH`     varchar(100) DEFAULT NULL COMMENT '中文名称',
    `NAME_EN`     varchar(200) DEFAULT NULL COMMENT '英文名称',
    `IS_SYSTEM`   varchar(1)   DEFAULT '0' COMMENT '系统初始化标志  1-是 0-否',
    `CREATE_DATE` datetime     DEFAULT NULL COMMENT '创建时间',
    `CREATE_BY`   varchar(32)  DEFAULT NULL COMMENT '创建人',
    `UPDATE_DATE` datetime     DEFAULT NULL COMMENT '更新时间',
    `UPDATE_BY`   varchar(32)  DEFAULT NULL COMMENT '更新人',
    `continent`   varchar(32)  DEFAULT NULL,
    `TENANT_ID`   varchar(32)  DEFAULT NULL COMMENT '租户ID',
    `ISO_TWO`     varchar(32)  DEFAULT NULL,
    `ISO_THREE`   varchar(32)  DEFAULT NULL,
    PRIMARY KEY (`ID`) USING BTREE,
    KEY `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  ROW_FORMAT = DYNAMIC COMMENT = '国家表';


-- 表说明：系统币别表
CREATE TABLE IF NOT EXISTS `bt_currency_init`
(
    `ID`           varchar(32) NOT NULL,
    `CUR_NAME`     varchar(30) DEFAULT NULL,
    `ENGLISH_CODE` varchar(30) DEFAULT NULL,
    `TENANT_ID`    varchar(32) DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`ID`) USING BTREE,
