-- 表说明：附件表
CREATE TABLE IF NOT EXISTS `sys_attachment_manager`
(
    ID VARCHAR(32) NOT NULL COMMENT 'id',
    USER_ID VARCHAR(32) NULL DEFAULT NULL COMMENT '用户ID',
    NAME VARCHAR(100) NULL DEFAULT NULL COMMENT '附件名称',
    RE_NAME VARCHAR(50) NULL DEFAULT NULL COMMENT '附件别名',
    TYPE VARCHAR(20) NULL DEFAULT NULL COMMENT '附件类型',
    SUFFIX VARCHAR(20) NULL DEFAULT NULL COMMENT '附件后缀',
    FILE_SIZE DECIMAL(10,2) NULL DEFAULT NULL COMMENT '附件大小',
    PATH TEXT NULL DEFAULT NULL COMMENT '附件地址',
    DESCRIPTION VARCHAR(225) NULL DEFAULT NULL COMMENT '附件描述',
    CATEGORY VARCHAR(30) NULL DEFAULT NULL COMMENT '附件分类',
    STATUS DECIMAL(2,0) NULL DEFAULT NULL COMMENT '状态',
    GROUP_ID VARCHAR(32) NULL DEFAULT NULL COMMENT '组别id',
    CREATE_DATE DATETIME NULL DEFAULT NULL,
    CREATE_BY VARCHAR(32) NULL DEFAULT NULL,
    UPDATE_DATE DATETIME NULL DEFAULT NULL,
    UPDATE_BY VARCHAR(32) NULL DEFAULT NULL,
    PRIMARY KEY (ID) USING BTREE
)
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_bin
  COMMENT = '附件表';

